/**
 * 摄像头参数基准值（基于1.65m标准角色）
 */
export const CAMERA_CONFIG = {
  // 基准高度
  BASE_HEIGHT: 1.65,

  // 摄像头高度
  BASE_CAMERA_HEIGHT: 2.8,

  // 摄像头距离
  BASE_CAMERA_DISTANCE: 5.0,
  BASE_FORWARD_DISTANCE: 6.0,
  BASE_BACKWARD_DISTANCE: 10.0,

  // 摄像头视线偏移
  BASE_LOOK_AT_OFFSET: 2.0,

  // 摄像头距离缩放因子
  // 用于非线性调整，让高个子角色的摄像头更远
  // 公式: distance = baseDistance * (height / baseHeight) ^ scaleFactor
  // scaleFactor > 1: 高个子角色摄像头距离增加更多
  // scaleFactor = 1: 线性缩放
  // scaleFactor < 1: 高个子角色摄像头距离增加较少
  DISTANCE_SCALE_FACTOR: 1.3,
} as const;

