<template>
  <div ref="containerRef" class="three-container">
    <VirtualJoystick
      ref="virtualJoystickRef"
      :is-orbit-control-active="uiState.isOrbitControlActive"
      :is-orbit-control-manually-activated="uiState.isOrbitControlManuallyActivated"
      @joystick-move="onJoystickMove"
      @run-toggle="onRunToggle"
      @touch-delta="onTouchDelta"
      @camera-rotate="onCameraRotate"
      @camera-rotation-speed="onCameraRotationSpeed"
      @operation-mode-change="onOperationModeChange"
    />

    <!-- 跳跃按钮 (独立) -->
    <div class="jump-button-container">
      <div
        class="jump-button center-button"
        :class="{ active: uiState.isJumping }"
        @touchstart.prevent.stop="onJumpStart"
        @touchend.prevent.stop="onJumpEnd"
        @mousedown.prevent.stop="onJumpStart"
        @mouseup.prevent.stop="onJumpEnd"
        @click.prevent.stop
      >
        <svg viewBox="0 0 48 48" fill="currentColor">
          <!-- 跳跃小人图标 - 更动感的设计 -->
          <!-- 头部 -->
          <circle cx="24" cy="10" r="5" />
          <!-- 身体 (稍微倾斜) -->
          <ellipse cx="24" cy="20" rx="3" ry="8" transform="rotate(5 24 20)" />
          <!-- 左臂 (大幅向上摆动) -->
          <ellipse cx="18" cy="16" rx="1.5" ry="6" transform="rotate(-45 18 16)" />
          <!-- 右臂 (向后摆动) -->
          <ellipse cx="30" cy="18" rx="1.5" ry="6" transform="rotate(25 30 18)" />
          <!-- 左腿 (向前踢) -->
          <ellipse cx="21" cy="30" rx="2" ry="8" transform="rotate(-25 21 30)" />
          <!-- 右腿 (向后蹬) -->
          <ellipse cx="27" cy="32" rx="2" ry="8" transform="rotate(35 27 32)" />

          <!-- 跳跃轨迹弧线 -->
          <path
            d="M8 38 Q24 28 40 38"
            stroke="currentColor"
            stroke-width="2.5"
            fill="none"
            opacity="0.7"
            stroke-dasharray="3,2"
          />

          <!-- 地面冲击波 -->
          <ellipse cx="24" cy="42" rx="12" ry="2" opacity="0.4" />
          <ellipse cx="24" cy="43" rx="8" ry="1" opacity="0.3" />
        </svg>
      </div>
    </div>

    <!-- 右侧竖向按钮组 -->
    <div class="vertical-button-group">
      <!-- 选择模型按钮 -->
      <div
        class="model-selector-button vertical-button"
        @click.prevent.stop="toggleModelSelector"
        @touchstart.prevent.stop
        @touchend.prevent.stop="toggleModelSelector"
        @mousedown.prevent.stop
        @mouseup.prevent.stop
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 人物图标 -->
          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
          <circle cx="12" cy="7" r="4"></circle>
        </svg>
      </div>

      <!-- 环绕按钮 -->
      <div
        class="orbit-button vertical-button"
        @touchstart.prevent.stop="onOrbitButtonStart"
        @touchend.prevent.stop="onOrbitButtonEnd"
        @mousedown.prevent.stop="onOrbitButtonStart"
        @mouseup.prevent.stop="onOrbitButtonEnd"
        @click.prevent.stop
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 圈形图标 -->
          <circle cx="12" cy="12" r="8" />
          <circle cx="12" cy="12" r="3" fill="currentColor" />
        </svg>
      </div>

      <!-- 全屏按钮 -->
      <div
        class="fullscreen-toggle vertical-button"
        :class="{ active: uiState.isFullscreen }"
        @click.prevent.stop="toggleFullscreen"
        @touchstart.prevent.stop
        @touchend.prevent.stop="toggleFullscreen"
        @mousedown.prevent.stop
        @mouseup.prevent.stop
      >
        <svg v-if="uiState.isFullscreen" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 退出全屏图标 -->
          <path
            d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"
          ></path>
        </svg>
        <svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 进入全屏图标 -->
          <path
            d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"
          ></path>
        </svg>
      </div>
    </div>

    <!-- 模型选择卡片 -->
    <Transition name="modal">
      <div v-if="uiState.showModelSelector" class="model-selector-overlay" @click.prevent.stop="closeModelSelector">
        <div class="model-selector-card" @click.prevent.stop>
          <!-- 头部区域 -->
          <div class="model-selector-header">
            <div class="header-content">
              <div class="header-icon">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path>
                  <circle cx="9" cy="7" r="4"></circle>
                  <path d="M22 21v-2a4 4 0 0 0-3-3.87"></path>
                  <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
                </svg>
              </div>
              <div class="header-text">
                <h3>选择角色模型</h3>
              </div>
            </div>
            <button class="close-btn" @click.prevent.stop="closeModelSelector">×</button>
          </div>

          <!-- 内容区域 -->
          <div class="model-selector-content">
            <div class="model-cards-container">
              <div
                v-for="(model, index) in availableModels"
                :key="model.id"
                class="model-card"
                :class="{
                  active: model.id === uiState.currentModelId,
                  selected: model.id === uiState.selectedModelId,
                }"
                :style="{ '--delay': index * 0.1 + 's' }"
                @click.prevent.stop="selectModelCard(model.id)"
                @touchstart.prevent.stop
                @touchend.prevent.stop="selectModelCard(model.id)"
                @mousedown.prevent.stop
                @mouseup.prevent.stop
              >
                <!-- 模型预览图 -->
                <div class="model-image-container">
                  <div class="image-wrapper">
                    <img :src="model.imagePath" :alt="model.name" class="model-image" @error="onImageError" />
                    <div class="image-overlay"></div>
                  </div>

                  <!-- 选中状态 -->
                  <div v-if="model.id === uiState.selectedModelId" class="selected-badge">
                    <div class="badge-icon">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" />
                      </svg>
                    </div>
                  </div>

                  <!-- 当前使用标识 -->
                  <div v-if="model.id === uiState.currentModelId" class="current-badge">
                    <div class="current-icon">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <circle cx="12" cy="12" r="10" />
                        <path d="M12 6v6l4 2" stroke="white" stroke-width="2" fill="none" />
                      </svg>
                    </div>
                  </div>

                  <!-- 悬停效果 -->
                  <div class="hover-overlay">
                    <div class="play-icon">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <polygon points="5,3 19,12 5,21"></polygon>
                      </svg>
                    </div>
                  </div>
                </div>

                <!-- 模型信息 -->
                <div class="model-info">
                  <div class="model-name">{{ model.name }}</div>
                  <div class="model-description">{{ model.describe }}</div>

                  <!-- 状态指示器 -->
                  <div class="model-status">
                    <div
                      class="status-dot"
                      :class="{
                        active: model.id === uiState.currentModelId,
                        selected: model.id === uiState.selectedModelId,
                      }"
                    ></div>
                    <span class="status-text">
                      {{
                        model.id === uiState.currentModelId
                          ? '当前使用'
                          : model.id === uiState.selectedModelId
                            ? '已选择'
                            : '点击选择'
                      }}
                    </span>
                  </div>
                </div>

                <!-- 装饰元素 -->
                <div class="card-decoration">
                  <div class="decoration-line"></div>
                </div>
              </div>
            </div>
          </div>

          <!-- 底部操作区 -->
          <div class="model-selector-footer">
            <div class="footer-info">
              <span class="model-count">{{ availableModels.length }} 个可用角色</span>
            </div>
            <div class="footer-buttons">
              <button
                class="upload-local-btn"
                @click="triggerLocalModelUpload"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path>
                  <polyline points="17,8 12,3 7,8"></polyline>
                  <line x1="12" y1="3" x2="12" y2="15"></line>
                </svg>
                <span>本地模型</span>
              </button>
              <button
                class="confirm-btn"
                :disabled="uiState.selectedModelId === uiState.currentModelId"
                @click.prevent.stop="confirmModelSelection"
                @touchstart.prevent.stop
                @touchend.prevent.stop="confirmModelSelection"
                @mousedown.prevent.stop
                @mouseup.prevent.stop
              >
                <span>{{ uiState.selectedModelId === uiState.currentModelId ? '已是当前模型' : '确认选择' }}</span>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <polyline points="9,18 15,12 9,6"></polyline>
                </svg>
              </button>
            </div>
          </div>

        </div>
      </div>
    </Transition>

    <!-- 隐藏的文件输入框 (放在外层避免被 @click.prevent.stop 影响) -->
    <input
      ref="fileInputRef"
      type="file"
      accept=".glb,.fbx"
      style="display: none"
      @change="handleLocalModelSelect"
    />

    <!-- Toast 提示 -->
    <Transition name="toast">
      <div v-if="uiState.showToast" class="toast">
        {{ uiState.toastMessage }}
      </div>
    </Transition>

    <!-- Debug面板 -->
    <DebugPanel
      :debug-manager="debugManager"
      :npc-manager="npcManager"
      :camera-sensitivity="cameraSensitivity"
      @config-change="onDebugConfigChange"
      @log-debug-info="onLogDebugInfo"
      @reset-physics="onResetPhysics"
    />
    <!-- 交互对话框 -->
    <InteractionDialog ref="interactionRef" />
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed } from 'vue';
import VirtualJoystick from './VirtualJoystick.vue';
import DebugPanel from './DebugPanel.vue';
import InteractionDialog from '../../components/InteractionDialog.vue';
import { ViewerSDK, LocalModelConfig, CharacterModelInfo, DialogType, CLIFF_DETECTION_CONFIG } from '@tencent/viewer-sdk';

// DOM 引用
const containerRef = ref<HTMLDivElement>();
const virtualJoystickRef = ref<InstanceType<typeof VirtualJoystick>>();
const interactionRef = ref<DialogType>();
const fileInputRef = ref<HTMLInputElement>();
// viewerSDK 实例
const viewerSDK = new ViewerSDK();

// 本地 UI 状态（用于模型选择器等本地功能）
const localUIState = ref({
  showModelSelector: false,
  selectedModelId: LocalModelConfig.default,
});

// 用于触发 Vue 响应式更新的状态
const pluginUIState = ref<{
  isOrbitControlActive: boolean;
  isOrbitControlManuallyActivated: boolean;
  isFullscreen: boolean;
  showToast: boolean;
  toastMessage: string;
  currentModelId: string;
  selectedModelId: string;
  isJumping: boolean;
}>({
  isOrbitControlActive: false,
  isOrbitControlManuallyActivated: false,
  isFullscreen: false,
  showToast: false,
  toastMessage: '',
  currentModelId: LocalModelConfig.default,
  selectedModelId: LocalModelConfig.default,
  isJumping: false,
});

// 从 viewerSDK 获取的响应式状态
const uiState = computed(() => ({
  ...pluginUIState.value,
  showModelSelector: localUIState.value.showModelSelector,
  selectedModelId: localUIState.value.selectedModelId,
}));

// 摄像机灵敏度（用于 DebugPanel）
const pluginCameraSensitivity = ref(0.003);
const cameraSensitivity = computed(() => pluginCameraSensitivity.value);

// 标记 viewerSDK 是否已初始化（用于触发 computed 重新计算）
const isPluginInitialized = ref(false);

// 获取 Debug 管理器（用于 DebugPanel）
const debugManager = computed(() => {
  // 依赖 isPluginInitialized 来触发重新计算
  if (!isPluginInitialized.value) return undefined;
  return viewerSDK?.getDebugManager();
});

// 获取 NPC 管理器（用于 DebugPanel）
const npcManager = computed(() => {
  // 依赖 isPluginInitialized 来触发重新计算
  if (!isPluginInitialized.value) return undefined;
  return viewerSDK?.getNPCManager();
});

// 获取正确的资源路径
function getAssetPath(path: string): string {
  if (import.meta.env.DEV) {
    return path.startsWith('/') ? path : `/${path}`;
  }
  return path.startsWith('/') ? `.${path}` : path;
}

// 可用的模型列表
const availableModels = ref(
  LocalModelConfig.models.map((model) => ({
    ...model,
    imagePath: getAssetPath(model.imagePath),
  })),
);

// 添加动态角色到模型列表
function addDynamicCharacterToModelList(characterInfo: CharacterModelInfo) {
  const modelId = `dynamic_${characterInfo.name}`;

  const existingModel = availableModels.value.find((model) => model.id === modelId);
  if (existingModel) {
    console.log(`🔄 动态模型已存在: ${characterInfo.name}`);
    return;
  }

  const newModel: CharacterModelInfo = {
    id: modelId,
    name: characterInfo.name,
    describe: '动态加载的角色模型',
    modelFilePath: characterInfo.modelFilePath,
    imagePath:
      'data:image/svg+xml;base64,',
    transform: characterInfo.transform,
    anim: characterInfo.anim,
  };

  availableModels.value.unshift(newModel);
  localUIState.value.selectedModelId = modelId;

  console.log(`✅ 动态角色已添加到模型列表: ${characterInfo.name} (${modelId})`);
}

onMounted(async () => {
  if (!containerRef.value) return;

  // 使用 viewerSDK 静态方法解析 URL 参数
  const urlParams = viewerSDK.parseURLParams('/viewer2');
  console.log('URL 参数:', urlParams);

  // 从 URL 参数构建角色信息
  const characterInfo = viewerSDK.buildCharacterInfoFromURLParams(urlParams);
  console.log('角色信息:', characterInfo);

  // 初始化 viewerSDK
  await viewerSDK.init({
    container: containerRef.value,
    sceneUrl: urlParams.sceneUrl,
    characterInfo,
    defaultOperationMode: 'dual',
    enableCliffDetection: true,
    cliffDetectionMode: 'slide',
    cliffDetectionConfig: {
      enabled: CLIFF_DETECTION_CONFIG.ENABLED,
      checkDistance: CLIFF_DETECTION_CONFIG.CHECK_DISTANCE,
      maxFallDistance: CLIFF_DETECTION_CONFIG.MAX_FALL_DISTANCE,
      safetyMargin: CLIFF_DETECTION_CONFIG.SAFETY_MARGIN,
    },
    interactionRef: interactionRef.value!,
  });

  // 监听 viewerSDK 状态变化，同步到 Vue 响应式系统
  viewerSDK.onUIStateChange((newState) => {
    Object.assign(pluginUIState.value, newState);
  });

  viewerSDK.onCameraSensitivityChange((newValue) => {
    pluginCameraSensitivity.value = newValue;
  });

  // 初始化状态同步
  Object.assign(pluginUIState.value, viewerSDK.uiState);
  pluginCameraSensitivity.value = viewerSDK.cameraSensitivity;

  // 标记插件已初始化，触发相关 computed 重新计算
  isPluginInitialized.value = true;

  // 设置外部组件回调（用于 VirtualJoystick）
  viewerSDK.setKeyboardEdgeArcCallback((direction, fadeOut) => {
    if (virtualJoystickRef.value) {
      virtualJoystickRef.value.showEdgeArcFromKeyboard(direction, fadeOut);
    }
  });

  viewerSDK.setEdgeArcFadeOutCallback(() => {
    if (virtualJoystickRef.value) {
      virtualJoystickRef.value.startEdgeArcFadeOut();
    }
  });

  // 开始动画循环
  viewerSDK.animate();
  // viewerSDK.animate();

  // 延迟同步当前模型状态
  setTimeout(() => {
    viewerSDK.syncCurrentModelState();

    // 如果有动态角色信息，添加到可用模型列表中
    const dynamicCharacterInfo = viewerSDK.getCharacterInfo();
    if (dynamicCharacterInfo) {
      addDynamicCharacterToModelList(dynamicCharacterInfo);
    }
  }, 1000);
});

onUnmounted(() => {
  viewerSDK?.dispose();
});

// ==================== 事件处理方法 ====================

function onJoystickMove(data: { x: number; y: number; distance: number; edgeRatio?: number }) {
  viewerSDK?.updateJoystick(data);
}

function onTouchDelta(delta: { x: number; y: number }) {
  viewerSDK?.updateTouchDelta(delta);
}

function onCameraRotate(rotation: number) {
  viewerSDK?.updateCameraRotation(rotation);
}

function onCameraRotationSpeed(speed: number) {
  viewerSDK?.updateCameraRotationSpeed(speed);
}

function onOperationModeChange(mode: 'auto' | 'single' | 'dual') {
  viewerSDK?.setOperationMode(mode);
}

function onRunToggle(isRunning: boolean) {
  viewerSDK?.toggleRun(isRunning);
}

// 跳跃按钮事件处理
function onJumpStart() {
  viewerSDK?.setJumpPressed(true);
}

function onJumpEnd() {
  viewerSDK?.setJumpPressed(false);
}

// 圈形按钮事件处理
function onOrbitButtonStart() {
  viewerSDK?.setAutoRotate(true);
}

function onOrbitButtonEnd() {
  viewerSDK?.setAutoRotate(false);
}

async function toggleFullscreen() {
  await viewerSDK?.toggleFullscreen();
}

// ==================== 模型选择器相关方法 ====================

function toggleModelSelector() {
  localUIState.value.showModelSelector = !localUIState.value.showModelSelector;
  if (localUIState.value.showModelSelector) {
    localUIState.value.selectedModelId = viewerSDK?.uiState.currentModelId || LocalModelConfig.default;
  }
}

function closeModelSelector() {
  localUIState.value.showModelSelector = false;
}

function selectModelCard(modelId: string) {
  localUIState.value.selectedModelId = modelId;
  console.log(`选择了模型: ${modelId}`);
}

async function confirmModelSelection() {
  const { selectedModelId } = localUIState.value;
  const currentModelId = viewerSDK?.uiState.currentModelId;

  if (selectedModelId === currentModelId) {
    closeModelSelector();
    return;
  }

  const selectedModel = availableModels.value.find((model) => model.id === selectedModelId);
  if (!selectedModel) {
    viewerSDK?.showToast('模型不存在');
    return;
  }

  try {
    viewerSDK?.showToast(`正在加载 ${selectedModel.name}...`);
    await viewerSDK?.switchCharacterModel(selectedModelId);
    viewerSDK?.showToast(`${selectedModel.name} 加载成功`);
    closeModelSelector();
  } catch (error) {
    console.error('模型切换失败:', error);
    viewerSDK?.showToast(`${selectedModel.name} 加载失败`);
  }
}

// 图片加载错误处理
function onImageError(event: Event) {
  const img = event.target as HTMLImageElement;
  console.warn('模型预览图片加载失败:', img.src);
  img.src =
    'data:image/svg+xml;base64,';
}

// ==================== 本地模型处理方法 ====================

// 触发文件选择
function triggerLocalModelUpload() {
  console.log('🔄 触发本地模型上传, fileInputRef:', fileInputRef.value);
  if (fileInputRef.value) {
    fileInputRef.value.click();
  } else {
    console.error('❌ fileInputRef 未找到');
  }
}

// 处理本地模型文件选择
async function handleLocalModelSelect(event: Event) {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];

  if (!file) return;

  // 检查文件类型
  const validExtensions = ['.glb', '.fbx'];
  const ext = file.name.toLowerCase().slice(file.name.lastIndexOf('.'));
  if (!validExtensions.includes(ext)) {
    viewerSDK?.showToast('只支持 .glb 和 .fbx 格式的模型文件');
    return;
  }

  // 检查文件大小 (100MB 限制)
  const maxSize = 100 * 1024 * 1024; // 100MB
  if (file.size > maxSize) {
    viewerSDK?.showToast('模型文件大小不能超过 100MB');
    return;
  }

  try {
    // 创建 Blob URL
    const blobUrl = URL.createObjectURL(file);

    // 生成唯一 ID
    const modelName = file.name.replace(/\.[^/.]+$/, ''); // 去掉扩展名
    const modelId = `local_${Date.now()}_${modelName}`;
    
    // 获取文件扩展名
    const fileType = ext.replace('.', '') as 'glb' | 'fbx';

    // 创建模型配置
    const localModelConfig: CharacterModelInfo = {
      id: modelId,
      name: modelName,
      describe: '本地上传的模型',
      modelFilePath: blobUrl,
      fileType, // 保存文件类型用于 Blob URL 加载
      imagePath: generateLocalModelIcon(),
      transform: {
        position: { x: 0, y: 0, z: 0 },
        rotation: { x: 0, y: 0, z: 0 },
      },
      anim: {
        isBuiltIn: true, // 使用内置动画
        animations: {
          Idle: 'Idle',
          Walking: 'Walk',
          Running: 'Run',
          Falling: 'Idle',
          Jumping: 'Idle',
        },
      },
    };

    // 添加到模型列表 (UI显示)
    availableModels.value.unshift(localModelConfig);

    // 添加到 SDK 的动态模型配置 (实际加载使用)
    viewerSDK?.getCharacterManager()?.addDynamicModelConfig(localModelConfig);

    // 选中这个模型
    localUIState.value.selectedModelId = modelId;

    // 自动应用本地模型
    viewerSDK?.showToast(`正在加载 "${modelName}"...`);
    console.log(`✅ 本地模型已添加: ${modelId}`, localModelConfig);

    try {
      await viewerSDK?.switchCharacterModel(modelId);
      viewerSDK?.showToast(`本地模型 "${modelName}" 加载成功`);
      closeModelSelector();
    } catch (switchError) {
      console.error('本地模型切换失败:', switchError);
      viewerSDK?.showToast(`模型 "${modelName}" 加载失败`);
    }
  } catch (error) {
    console.error('本地模型加载失败:', error);
    viewerSDK?.showToast('模型加载失败，请检查文件格式');
  }

  // 清空 input，允许重复选择同一文件
  input.value = '';
}

// 生成本地模型的默认图标 (SVG)
function generateLocalModelIcon(): string {
  return 'data:image/svg+xml;base64,';
}

// ==================== Debug 事件处理方法 ====================

function onDebugConfigChange(config: any) {
  viewerSDK?.updateDebugConfig(config);
}

function onLogDebugInfo() {
  viewerSDK?.logDebugInfo();
}

function onResetPhysics() {
  viewerSDK?.resetPhysics();
}
</script>

<style scoped>
.three-container {
  width: 100%;
  height: 100%;
  position: relative;
}

/* Toast 提示 */
.toast {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.85);
