  border: 1px solid rgba(255, 255, 255, 0.2);
  color: rgba(255, 255, 255, 0.9);
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
  font-size: 24px;
  font-weight: 300;
  line-height: 1;
  padding: 0;
}

.close-btn:hover {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.3);
  transform: scale(1.05);
  color: #fff;
}

/* 内容区域 */
.model-selector-content {
  padding: 16px;
  max-height: 35vh;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.3) transparent;
}

.model-selector-content::-webkit-scrollbar {
  width: 6px;
}

.model-selector-content::-webkit-scrollbar-track {
  background: transparent;
}

.model-selector-content::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.3);
  border-radius: 3px;
}

/* 模型卡片容器 */
.model-cards-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

/* 单个模型卡片 */
.model-card {
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 0;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(10px);
  animation: cardSlideIn 0.6s ease var(--delay) both;
  width: 100%;
  max-width: 280px;
  display: flex;
  flex-direction: row;
  height: 100px;
  pointer-events: auto;
}

.model-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(100, 50, 200, 0.1), rgba(50, 100, 200, 0.1));
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: 1;
}

.model-card:hover::before {
  opacity: 1;
}

.model-card:hover {
  transform: translateY(-8px) scale(1.02);
  border-color: rgba(100, 50, 200, 0.4);
  box-shadow:
    0 20px 40px rgba(0, 0, 0, 0.3),
    0 0 0 1px rgba(100, 50, 200, 0.2),
    0 0 60px rgba(100, 50, 200, 0.1);
}

.model-card.active {
  background: linear-gradient(145deg, rgba(100, 50, 200, 0.15), rgba(50, 100, 200, 0.15));
  border-color: rgba(100, 50, 200, 0.6);
  box-shadow:
    0 12px 32px rgba(100, 50, 200, 0.3),
    0 0 0 1px rgba(100, 50, 200, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.model-card.active:hover {
  transform: translateY(-8px) scale(1.02);
  box-shadow:
    0 20px 40px rgba(100, 50, 200, 0.4),
    0 0 0 1px rgba(100, 50, 200, 0.6),
    0 0 60px rgba(100, 50, 200, 0.2);
}

.model-card.selected {
  background: linear-gradient(145deg, rgba(50, 150, 50, 0.15), rgba(50, 200, 100, 0.15));
  border-color: rgba(50, 150, 50, 0.6);
  box-shadow:
    0 8px 24px rgba(50, 150, 50, 0.3),
    0 0 0 1px rgba(50, 150, 50, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.model-card.selected:hover {
  transform: translateY(-6px) scale(1.01);
  box-shadow:
    0 16px 32px rgba(50, 150, 50, 0.4),
    0 0 0 1px rgba(50, 150, 50, 0.6),
    0 0 40px rgba(50, 150, 50, 0.2);
}

/* 模型图片容器 */
.model-image-container {
  position: relative;
  width: 80px;
  height: 100px;
  overflow: hidden;
  border-radius: 12px 0 0 12px;
  flex-shrink: 0;
}

.image-wrapper {
