<template>
  <div v-if="showDebugPanel" class="debug-panel">
    <div class="debug-header">
      <h3>🔧 Debug Panel</h3>
      <button @click="togglePanel" class="close-btn">×</button>
    </div>

    <div class="debug-content">
      <!-- 可视化控制 -->
      <div class="debug-section">
        <h4>🎨 可视化</h4>
        <div class="debug-controls">
          <label class="debug-checkbox">
            <input
              type="checkbox"
              v-model="debugConfig.showColliders"
              @change="onConfigChange"
            />
            <span>显示碰撞体</span>
          </label>

          <label class="debug-checkbox">
            <input
              type="checkbox"
              v-model="debugConfig.showCharacterController"
              @change="onConfigChange"
            />
            <span>显示角色控制器</span>
          </label>



          <label class="debug-checkbox">
            <input
              type="checkbox"
              v-model="debugConfig.wireframeMode"
              @change="onConfigChange"
            />
            <span>线框模式</span>
          </label>

          <label class="debug-checkbox">
            <input
              type="checkbox"
              v-model="debugConfig.showTerrain"
              @change="onConfigChange"
            />
            <span>显示地形碰撞</span>
          </label>

          <label class="debug-checkbox">
            <input
              type="checkbox"
              v-model="debugConfig.showCliffDetection"
              @change="onConfigChange"
            />
            <span>显示悬崖检测</span>
          </label>
        </div>
      </div>

      <!-- 性能统计 -->
      <div class="debug-section">
        <h4>📊 性能统计</h4>
        <div class="stats-grid">
          <div class="stat-item">
            <span class="stat-label">FPS:</span>
            <span class="stat-value" :class="getFpsClass(performanceStats.fps)">
              {{ performanceStats.fps }}
            </span>
          </div>

          <div class="stat-item">
            <span class="stat-label">帧时间:</span>
            <span class="stat-value">{{ performanceStats.frameTime.toFixed(2) }}ms</span>
          </div>

          <div class="stat-item">
            <span class="stat-label">内存:</span>
            <span class="stat-value">{{ performanceStats.memoryUsage.toFixed(1) }}MB</span>
          </div>
        </div>
      </div>

      <!-- 物理信息 -->
      <div class="debug-section">
        <h4>🌍 物理世界</h4>
        <div class="physics-info">
          <div class="info-item">
            <span class="info-label">刚体数量:</span>
            <span class="info-value">{{ physicsInfo.rigidBodyCount || 0 }}</span>
          </div>

          <div class="info-item">
            <span class="info-label">角色位置:</span>
            <span class="info-value">
              {{ formatVector3(physicsInfo.characterPosition) }}
            </span>
          </div>

          <div class="info-item">
            <span class="info-label">在地面上:</span>
            <span class="info-value" :class="physicsInfo.isCharacterGrounded ? 'grounded' : 'airborne'">
              {{ physicsInfo.isCharacterGrounded ? '是' : '否' }}
            </span>
          </div>

          <div class="info-item">
            <span class="info-label">垂直速度:</span>
            <span class="info-value" :class="getVelocityClass(physicsInfo.characterVerticalVelocity)">
              {{ physicsInfo.characterVerticalVelocity?.toFixed(2) || '0.00' }} m/s
            </span>
          </div>

          <div class="info-item">
            <span class="info-label">重力:</span>
            <span class="info-value">
              {{ formatVector3(physicsInfo.worldGravity) }}
            </span>
          </div>
        </div>
      </div>

      <!-- 🔥 新增：悬崖检测控制 -->
      <div class="debug-section">
        <h4>🚫 悬崖检测</h4>
        <div class="cliff-detection-controls">
          <label class="debug-checkbox">
            <input
              type="checkbox"
              v-model="cliffDetectionConfig.enabled"
              @change="onCliffDetectionChange"
            />
            <span>启用悬崖检测</span>
          </label>

          <div v-if="cliffDetectionConfig.enabled" class="cliff-detection-options">
            <div class="control-group">
              <label class="control-label">行为模式:</label>
              <select 
                v-model="cliffDetectionConfig.behaviorMode" 
                @change="onCliffDetectionChange"
                class="debug-select"
              >
                <option value="block">阻止 (Block)</option>
                <option value="slide">滑动 (Slide)</option>
                <option value="slow">减速 (Slow)</option>
              </select>
            </div>

            <div class="control-group">
              <label class="control-label">检测距离:</label>
              <input 
                type="range" 
                min="0.5" 
                max="3.0" 
                step="0.1"
                v-model.number="cliffDetectionConfig.checkDistance"
                @input="onCliffDetectionConfigChange"
                class="debug-slider"
              />
              <span class="control-value">{{ cliffDetectionConfig.checkDistance.toFixed(1) }}m</span>
            </div>

            <div class="control-group">
              <label class="control-label">最大掉落高度:</label>
              <input 
                type="range" 
                min="1.0" 
                max="10.0" 
                step="0.5"
                v-model.number="cliffDetectionConfig.maxFallDistance"
                @input="onCliffDetectionConfigChange"
                class="debug-slider"
              />
              <span class="control-value">{{ cliffDetectionConfig.maxFallDistance.toFixed(1) }}m</span>
            </div>

            <div class="control-group">
              <label class="control-label">安全边距:</label>
              <input 
                type="range" 
                min="0.1" 
                max="1.0" 
                step="0.1"
                v-model.number="cliffDetectionConfig.safetyMargin"
                @input="onCliffDetectionConfigChange"
                class="debug-slider"
              />
              <span class="control-value">{{ cliffDetectionConfig.safetyMargin.toFixed(1) }}m</span>
            </div>
          </div>

          <div class="cliff-detection-status">
            <div class="info-item">
              <span class="info-label">当前状态:</span>
              <span class="info-value" :class="cliffDetectionConfig.enabled ? 'enabled' : 'disabled'">
                {{ cliffDetectionConfig.enabled ? '启用' : '禁用' }}
              </span>
            </div>
            <div class="info-item">
              <span class="info-label">行为模式:</span>
              <span class="info-value mode-indicator" :class="`mode-${cliffDetectionConfig.behaviorMode}`">
                {{ getModeDisplayName(cliffDetectionConfig.behaviorMode) }}
              </span>
            </div>
          </div>
        </div>
      </div>

      <!-- NPC管理 -->
      <div class="debug-section">
        <h4>🤖 NPC管理</h4>
        
        <div class="npc-info">
          <div class="info-item">
            <span class="info-label">NPC数量:</span>
            <span class="info-value">{{ npcCount }}</span>
          </div>
        </div>

        <div class="npc-controls">
          <div class="control-group">
            <label>创建位置:</label>
            <div class="position-inputs">
              <input
                type="number"
                v-model.number="npcCreatePosition.x"
                placeholder="X"
                step="0.1"
                class="position-input"
              />
              <input
                type="number"
                v-model.number="npcCreatePosition.y"
                placeholder="Y"
                step="0.1"
                class="position-input"
              />
              <input
                type="number"
                v-model.number="npcCreatePosition.z"
                placeholder="Z"
                step="0.1"
                class="position-input"
              />
              <button @click="setNPCPositionToPlayer" class="position-btn" title="设置为玩家位置">
                📍玩家位置
              </button>
            </div>
          </div>

          <div class="control-group">
            <label>指定模型ID (可选):</label>
            <select v-model="selectedNPCModelId" class="model-select">
              <option value="">随机选择</option>
              <option v-for="model in availableModels" :key="model.id" :value="model.id">
                {{ model.name }} ({{ model.id }})
              </option>
            </select>
          </div>

          <div class="npc-buttons">
            <button @click="createSingleNPC" class="debug-btn">
              ➕ 创建单个NPC
            </button>
            
            <button @click="createRandomNPCs" class="debug-btn">
              🎲 随机创建5个NPC
            </button>
            
            <div class="button-row">
              <button @click="setAllNPCsWander" class="debug-btn primary">
                🚶 全部漫游
              </button>
              <button @click="setAllNPCsIdle" class="debug-btn warning">
                🧍 全部静止
              </button>
            </div>
            
            <button @click="clearAllNPCs" class="debug-btn danger">
              🗑️ 清除所有NPC
            </button>
          </div>

          <div class="npc-list" v-if="npcList.length > 0">
            <h5>NPC列表:</h5>
            <div class="npc-item" v-for="npc in npcList" :key="npc.id">
              <div class="npc-item-info">
                <span class="npc-name">{{ npc.modelConfig.name }}</span>
                <span class="npc-id">({{ npc.id }})</span>
              </div>
              <div class="npc-item-controls">
                <button @click="setNPCWander(npc.id)" class="small-btn primary" title="漫游模式">
                  🚶 漫游
                </button>
                <button @click="setNPCIdle(npc.id)" class="small-btn warning" title="静止模式">
                  🧍 静止
                </button>
                <button @click="setNPCPathfindToPlayer(npc.id)" class="small-btn success" title="寻路到玩家">
                  🎯 寻路
                </button>
                <button @click="toggleNPCAnimation(npc.id)" class="small-btn" title="切换动画">
                  🎭
                </button>
                <button @click="removeNPC(npc.id)" class="small-btn danger" title="删除">
                  ❌
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- 控制按钮 -->
      <div class="debug-section">
        <h4>🎮 控制</h4>

        <!-- 摄像机灵敏度信息 -->
        <div class="camera-sensitivity-info">
          <div class="info-label">摄像机灵敏度</div>
          <div class="info-value">{{ cameraSensitivity.toFixed(6) }} 弧度/像素</div>
          <div class="info-value-alt">{{ (cameraSensitivity * deviceDPI).toFixed(4) }} 弧度/英寸</div>
        </div>

        <div class="control-buttons">
          <button @click="logDebugInfo" class="debug-btn">
            📝 打印调试信息
          </button>

          <button @click="resetPhysics" class="debug-btn">
            🔄 重置物理世界
          </button>

        </div>
      </div>
    </div>
  </div>

  <!-- Debug toggle button -->
  <button
    v-if="!showDebugPanel"
    @click="togglePanel"
    class="debug-toggle-btn"
    title="打开Debug面板"
  >
    🔧
  </button>
</template>

<script setup lang="ts">
import { ref, reactive, computed, onMounted, onUnmounted } from 'vue';
import type { DebugConfig, PerformanceStats } from '@/infranstructure/viewers/scene-viewer/debug-manager';
import type { NPCInstance } from '@/infranstructure/viewers/scene-viewer';
import { LocalModelConfig } from '@/infranstructure/viewers/scene-viewer/constant';

interface PhysicsInfo {
  rigidBodyCount: number;
  characterPosition: { x: number; y: number; z: number } | null;
  isCharacterGrounded: boolean;
  characterVerticalVelocity: number;
  worldGravity: { x: number; y: number; z: number } | null;
}

// Props
interface Props {
  debugManager?: any;
  npcManager?: any;
  cameraSensitivity?: number;
}

const props = withDefaults(defineProps<Props>(), {
  cameraSensitivity: 0.003,
});

// Emits
const emit = defineEmits<{
  configChange: [config: DebugConfig];
  logDebugInfo: [];
  resetPhysics: [];
  createNPC: [config: any];
  removeNPC: [npcId: string];
  clearAllNPCs: [];
}>();

// State
const showDebugPanel = ref(false);

// 设备DPI计算
const deviceDPI = window.devicePixelRatio * 96; // 假设标准DPI为96

// 摄像机灵敏度计算属性
const cameraSensitivity = computed(() => props.cameraSensitivity || 0.003);

const debugConfig = reactive<DebugConfig>({
  showColliders: false,
  showCharacterController: false,
  showPerformanceStats: true,
  showPhysicsInfo: true,
  wireframeMode: false,
  showTerrain: false,
  showCliffDetection: false, // 🔥 新增：悬崖检测可视化
});

// 🔥 新增：悬崖检测配置
const cliffDetectionConfig = reactive({
  enabled: true,
  behaviorMode: 'slide' as 'block' | 'slide' | 'slow',
  checkDistance: 1.2,
  maxFallDistance: 3.0,
  safetyMargin: 0.3,
});

const performanceStats = reactive<PerformanceStats>({
  fps: 0,
  frameTime: 0,
  physicsTime: 0,
  renderTime: 0,
  memoryUsage: 0
});

const physicsInfo = reactive<PhysicsInfo>({
  rigidBodyCount: 0,
  characterPosition: null,
  isCharacterGrounded: false,
  characterVerticalVelocity: 0,
  worldGravity: null
});

// NPC相关状态
const npcCreatePosition = reactive({
  x: 0,
  y: 1,  // 修改为地面附近高度,物理引擎会让NPC自然下落到地面
  z: 5
});

const selectedNPCModelId = ref('');
const npcList = ref<NPCInstance[]>([]);
const npcCount = computed(() => npcList.value.length);

// 可用模型列表
const availableModels = computed(() => {
  return LocalModelConfig.models;
});

let updateInterval: any | null = null;

// Methods
function togglePanel() {
  showDebugPanel.value = !showDebugPanel.value;
}

function onConfigChange() {
  emit('configChange', { ...debugConfig });
}

function logDebugInfo() {
  emit('logDebugInfo');
}

function resetPhysics() {
  emit('resetPhysics');
}

// 🔥 新增：悬崖检测相关方法
function onCliffDetectionChange() {
  // 发送悬崖检测启用/禁用和行为模式变化
  emit('configChange', { 
    ...debugConfig,
    cliffDetectionEnabled: cliffDetectionConfig.enabled,
    cliffBehaviorMode: cliffDetectionConfig.behaviorMode
  });
}

function onCliffDetectionConfigChange() {
  // 发送悬崖检测配置参数变化
  emit('configChange', { 
    ...debugConfig,
    cliffDetectionConfig: {
      checkDistance: cliffDetectionConfig.checkDistance,
      maxFallDistance: cliffDetectionConfig.maxFallDistance,
      safetyMargin: cliffDetectionConfig.safetyMargin,
    }
  });
}

function getModeDisplayName(mode: string): string {
  switch (mode) {
    case 'block': return '阻止';
    case 'slide': return '滑动';
    case 'slow': return '减速';
    default: return mode;
  }
}

// NPC相关方法
function setNPCPositionToPlayer() {
  if (props.physicsWorldManager) {
    const playerPos = props.physicsWorldManager.getCharacterPosition();
    npcCreatePosition.x = Math.round(playerPos.x * 10) / 10;
    npcCreatePosition.y = Math.round(playerPos.y * 10) / 10;
    npcCreatePosition.z = Math.round(playerPos.z * 10) / 10;
    console.log(`📍 NPC创建位置已设置为玩家位置: (${npcCreatePosition.x}, ${npcCreatePosition.y}, ${npcCreatePosition.z})`);
  }
}

async function createSingleNPC() {
  try {
    const config = {
      position: { x: npcCreatePosition.x, y: npcCreatePosition.y, z: npcCreatePosition.z },
      modelId: selectedNPCModelId.value || undefined
    };
    
    if (props.npcManager) {
      await props.npcManager.createNPC(config);
      updateNPCList();
    }
  } catch (error) {
    console.error('创建NPC失败:', error);
  }
}

async function createRandomNPCs() {
  try {
    if (props.npcManager) {
      const centerPosition = { x: npcCreatePosition.x, y: npcCreatePosition.y, z: npcCreatePosition.z };
      await props.npcManager.createRandomNPCsInArea(centerPosition, 3, 5);
      updateNPCList();
    }
  } catch (error) {
    console.error('批量创建NPC失败:', error);
  }
}

function clearAllNPCs() {
  if (props.npcManager) {
    props.npcManager.dispose();
    updateNPCList();
  }
}

function removeNPC(npcId: string) {
  if (props.npcManager) {
    props.npcManager.removeNPC(npcId);
    updateNPCList();
  }
}

function toggleNPCAnimation(npcId: string) {
  if (props.npcManager) {
    const npc = props.npcManager.getNPC(npcId);
    if (npc) {
      // 在不同动画之间切换
      const animations = ['Idle', 'Walking', 'Running'];
      const currentIndex = Math.floor(Math.random() * animations.length);
      const animationName = animations[currentIndex];
      
      props.npcManager.setNPCAnimation(npcId, animationName, true);
      console.log(`NPC ${npcId} 动画切换为: ${animationName}`);
    }
  }
}

// 设置NPC为漫游模式
function setNPCWander(npcId: string) {
  if (props.npcManager) {
    const npcInstance = props.npcManager.getNPC(npcId);
    if (npcInstance && npcInstance.npc) {
      npcInstance.npc.setMovementPattern('wander');
      console.log(`🚶 NPC ${npcId} 设置为漫游模式`);
    }
  }
}

// 设置NPC为静止模式
function setNPCIdle(npcId: string) {
  if (props.npcManager) {
    const npcInstance = props.npcManager.getNPC(npcId);
    if (npcInstance && npcInstance.npc) {
      npcInstance.npc.setMovementPattern('idle');
      console.log(`🧍 NPC ${npcId} 设置为静止模式`);
    }
  }
}

// 设置NPC寻路到玩家位置
function setNPCPathfindToPlayer(npcId: string) {
  if (!props.npcManager) {
    console.warn('⚠️ NPC管理器未初始化');
    return;
  }

  const success = props.npcManager.setNPCPathfindToPlayer(npcId);
  if (success) {
    console.log(`✅ NPC ${npcId} 寻路指令已发送`);
  }
}

// 设置所有NPC为漫游模式
function setAllNPCsWander() {
  if (props.npcManager) {
    const allNPCs = props.npcManager.getAllNPCs();
    allNPCs.forEach((npcInstance: NPCInstance) => {
      if (npcInstance.npc) {
        npcInstance.npc.setMovementPattern('wander');
      }
    });
    console.log(`🚶 所有NPC (${allNPCs.length}个) 已设置为漫游模式`);
  }
}

// 设置所有NPC为静止模式
function setAllNPCsIdle() {
  if (props.npcManager) {
    const allNPCs = props.npcManager.getAllNPCs();
    allNPCs.forEach((npcInstance: NPCInstance) => {
      if (npcInstance.npc) {
        npcInstance.npc.setMovementPattern('idle');
      }
    });
    console.log(`🧍 所有NPC (${allNPCs.length}个) 已设置为静止模式`);
  }
}

function updateNPCList() {
  if (props.npcManager) {
    npcList.value = props.npcManager.getAllNPCs();
  }
}

function getFpsClass(fps: number): string {
  if (fps >= 50) return 'fps-good';
  if (fps >= 30) return 'fps-ok';
  return 'fps-bad';
}

function getVelocityClass(velocity: number): string {
  if (velocity > 1) return 'velocity-up';
  if (velocity < -1) return 'velocity-down';
  return 'velocity-stable';
}

function formatVector3(vec: { x: number; y: number; z: number } | null): string {
  if (!vec) return 'N/A';
  return `(${vec.x.toFixed(2)}, ${vec.y.toFixed(2)}, ${vec.z.toFixed(2)})`;
}

function updateStats() {
  if (props.debugManager) {
    const stats = props.debugManager.getPerformanceStats();
    Object.assign(performanceStats, stats);

    const physics = props.debugManager.getPhysicsInfo();
    if (physics) {
      Object.assign(physicsInfo, physics);
    }

    // 同步调试配置状态
    Object.assign(debugConfig, props.debugManager.config);
  }
  
  // 更新NPC列表
  updateNPCList();
}

// Lifecycle
onMounted(() => {
  // 每秒更新统计信息
  updateInterval = setInterval(updateStats, 1000);

  // 监听键盘事件
  const handleKeyDown = (event: KeyboardEvent) => {
    // F1 键切换debug面板
    if (event.key === 'F1') {
      event.preventDefault();
      togglePanel();
    }

    // F2 键切换碰撞体可视化
    if (event.key === 'F2') {
      event.preventDefault();
      debugConfig.showColliders = !debugConfig.showColliders;
      onConfigChange();
    }

    // F3 键切换线框模式
    if (event.key === 'F3') {
      event.preventDefault();
      debugConfig.wireframeMode = !debugConfig.wireframeMode;
      onConfigChange();
    }
  };

  document.addEventListener('keydown', handleKeyDown);

  // 清理函数
  onUnmounted(() => {
    if (updateInterval) {
      clearInterval(updateInterval);
    }
    document.removeEventListener('keydown', handleKeyDown);
  });
});
</script>

